const { formatRecord } = require('../utils/dataFormat');

const Product = {
  table: process.env.DYNAMODB_TABLE_NAME,

  schema: {
    pk: 'id',
    sk: 'type',
    attributes: {
      id: 'string',
      name: 'string',
      description: 'string',
      price: 'number',
      createdAt: 'timestamp',
      updatedAt: 'timestamp',
      status: 'string'
    },
    defaults: {
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      status: 'active'
    }
  },

  formatInput: (data) => {
    // Clean and validate input data
    data = { ...data };

    // Remove reserved keys
    if (data.createdAt && !data.createdAt.includes('T')) {
      delete data.createdAt;
    }

    return data;
  },

  formatOutput: (data) => {
    return formatRecord(data);
  }
};

module.exports = Product;
```

