### 3. API Gateway Lambda Authorizer

You can also implement a custom Lambda authorizer for identity verification:

**src/lambda/authorizers/customAuth.js**
```javascript
const jwt = require('jsonwebtoken');

exports.handler = async (event) => {
  try {
    const authorization = event.headers.authorization;

    if (!authorization || !authorization.startsWith('Bearer ')) {
      return failResponse('Missing authorization header');
    }

    const token = authorization.split(' ')[1];

    // Verify JWT token
    const payload = jwt.verify(
      token,
      process.env.JWT_SECRET,
      { algorithms: ['RS256', 'HS256'] }
    );

    // Check token claims
    if (!payload.sub || !payload.email) {
      return failResponse('Invalid token claims');
    }

    // Check role permissions
    const claims = payload;
    const context = {
      user: claims.sub,
      email: claims.email
    };

    return successResponse({
      isAuthorized: true,
      userId: claims.sub,
      email: claims.email,
      roles: claims.roles || []
    });

  } catch (error) {
    return failResponse('Invalid token');
  }
